"""Bounded character-prefix-aware DataFrame reordering."""

import heapq
from typing import List, Tuple

import numpy as np
import pandas as pd

from solver import Algorithm


class Evolved(Algorithm):
    """Choose a constrained column permutation using exact serialized LCP reuse."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional frame and the most recently returned row orders."""
        self.df = df
        self._last_orders = None

    @staticmethod
    def _cell_string(value) -> str:
        """Serialize a scalar exactly as scoring does, mapping scalar missing values to ''."""
        missing = pd.isna(value)
        if isinstance(missing, (bool, np.bool_)) and bool(missing):
            return ""
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Return the common-prefix length using binary-search slice comparisons."""
        if left == right:
            return len(left)
        lo, hi = 0, min(len(left), len(right))
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if left[:mid] == right[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    @classmethod
    def _trie_score(cls, strings: List[str]) -> int:
        """Compute ideal character-Trie reuse from lexicographically adjacent rows."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        total = 0
        previous = ordered[0]
        for current in ordered[1:]:
            total += len(current) if current == previous else cls._lcp(previous, current)
            previous = current
        return total

    @staticmethod
    def _positions(columns):
        """Map stringified labels to their unique source-column positions."""
        result = {}
        for i, value in enumerate(columns):
            result.setdefault(str(value), []).append(i)
        return result

    @classmethod
    def _edges(cls, columns, dependencies, blocks):
        """Translate dependencies and merge chains into directed column edges."""
        positions = cls._positions(columns)
        result = []
        seen = set()

        def add(left, right):
            """Add one valid directed edge unless it is redundant."""
            if left != right and (left, right) not in seen:
                seen.add((left, right))
                result.append((left, right))

        for pair in dependencies or []:
            if len(pair) == 2:
                left = positions.get(str(pair[0]), [])
                right = positions.get(str(pair[1]), [])
                if len(left) == 1 and len(right) == 1:
                    add(left[0], right[0])

        for block in blocks:
            for left, right in zip(block, block[1:]):
                add(left, right)
        return result

    @classmethod
    def _constrained_order(cls, width, preference, columns, dependencies, blocks):
        """Topologically repair a preference while preserving all requested constraints."""
        outgoing = [[] for _ in range(width)]
        indegree = [0] * width
        for left, right in cls._edges(columns, dependencies, blocks):
            outgoing[left].append(right)
            indegree[right] += 1

        rank = {column: i for i, column in enumerate(preference)}
        queue = [
            (rank.get(i, width + i), i)
            for i in range(width)
            if indegree[i] == 0
        ]
        heapq.heapify(queue)

        answer = []
        while queue:
            _, node = heapq.heappop(queue)
            answer.append(node)
            for successor in outgoing[node]:
                indegree[successor] -= 1
                if indegree[successor] == 0:
                    heapq.heappush(
                        queue, (rank.get(successor, width + successor), successor)
                    )
        return answer if len(answer) == width else list(preference)

    @staticmethod
    def _merge_blocks(width, columns, requested):
        """Build ordered atomic blocks from valid pairwise merge requests."""
        parent = list(range(width))

        def find(value):
            """Find a disjoint-set root with path compression."""
            while parent[value] != value:
                parent[value] = parent[parent[value]]
                value = parent[value]
            return value

        positions = {}
        for i, value in enumerate(columns):
            positions.setdefault(str(value), []).append(i)

        for pair in requested or []:
            if len(pair) != 2:
                continue
            left = positions.get(str(pair[0]), [])
            right = positions.get(str(pair[1]), [])
            if len(left) == 1 and len(right) == 1:
                a, b = find(left[0]), find(right[0])
                if a != b:
                    parent[b] = a

        groups = {}
        for i in range(width):
            groups.setdefault(find(i), []).append(i)
        return sorted((sorted(group) for group in groups.values()), key=lambda x: x[0])

    @classmethod
    def _column_stats(cls, text):
        """Return equality repetition mass and exact within-column character LCP mass."""
        rows, width = text.shape
        stats = []
        for column in range(width):
            values = list(text[:, column])
            counts = {}
            for value in values:
                counts[value] = counts.get(value, 0) + 1

            repeat = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            ordinary = sum(
                len(value) * max(0, count - 1)
                for value, count in counts.items()
            )
            prefix = 0
            ordered = sorted(values)
            for left, right in zip(ordered, ordered[1:]):
                prefix += len(left) if left == right else cls._lcp(left, right)

            total = sum(len(value) for value in values)
            stats.append((repeat, ordinary, total, prefix))
        return stats

    @staticmethod
    def _affinity(text, left, right):
        """Measure repeated right-field character mass conditional on a left field."""
        groups = {}
        for row in range(text.shape[0]):
            groups.setdefault(text[row, left], []).append(row)

        score = 0
        for group in groups.values():
            if len(group) < 2:
                continue
            counts = {}
            for row in group:
                value = text[row, right]
                counts[value] = counts.get(value, 0) + 1
            score += sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
        return score

    @classmethod
    def _block_candidates(cls, text, stats, blocks):
        """Produce at most two bounded block-topology preferences."""
        if len(blocks) <= 1:
            return [sum(blocks, [])]

        mass = [sum(stats[c][0] for c in block) for block in blocks]
        active = sorted(
            range(len(blocks)),
            key=lambda i: (-mass[i], blocks[i][0]),
        )[:32]
        reps = [block[:2] for block in blocks]
        affinity = {}

        for left in active:
            for right in active:
                if left == right:
                    continue
                affinity[left, right] = sum(
                    cls._affinity(text, a, b)
                    for a in reps[left]
                    for b in reps[right]
                )

        beam = [((seed,), set(active) - {seed}, 0) for seed in active]
        for _ in range(max(0, len(active) - 1)):
            expanded = []
            for path, remaining, score in beam:
                if not remaining:
                    expanded.append((path, remaining, score))
                    continue
                previous = path[-1]
                for successor in remaining:
                    expanded.append((
                        path + (successor,),
                        remaining - {successor},
                        score + affinity.get((previous, successor), 0),
                    ))
            if not expanded:
                break
            expanded.sort(key=lambda x: (-x[2], x[0]))
            beam = expanded[:4]

        answers = []
        seen = set()
        for path, _, score in sorted(beam, key=lambda x: (-x[2], x[0])):
            used = set(path)
            tail = sorted(
                (i for i in range(len(blocks)) if i not in used),
                key=lambda i: (-mass[i], blocks[i][0]),
            )
            flat = tuple(
                c for block_index in path + tuple(tail)
                for c in blocks[block_index]
            )
            if flat not in seen:
                seen.add(flat)
                answers.append(list(flat))
            if len(answers) == 2:
                break
        return answers or [sum(blocks, [])]

    @staticmethod
    def _serialize(text, orders):
        """Serialize every source row according to its row-specific column order."""
        return [
            "".join(text[row, column] for column in orders[row])
            for row in range(text.shape[0])
        ]

    @staticmethod
    def _materialize(df, source, orders, serialized):
        """Sort by serialized keys and copy original cells without changing their values."""
        row_order = sorted(
            range(source.shape[0]),
            key=lambda row: (serialized[row], row),
        )
        values = np.empty(source.shape, dtype=object)
        public_orders = []

        for output_row, source_row in enumerate(row_order):
            order = orders[source_row]
            values[output_row, :] = [source[source_row, c] for c in order]
            public_orders.append([df.columns[c] for c in order])

        result = pd.DataFrame(
            values,
            index=df.index.take(row_order),
            columns=list(df.columns),
        )
        return result, public_orders

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List]]:
        """Evaluate equality-ranked, prefix-ranked, and bounded block candidates exactly."""
        if not isinstance(df, pd.DataFrame):
            raise TypeError("df must be a pandas DataFrame")

        rows, width = df.shape
        if rows == 0 or width == 0:
            result = df.copy()
            orders = [[] for _ in range(rows)]
            self._last_orders = orders
            return result, orders

        source = df.to_numpy(dtype=object, copy=True)
        text = np.empty((rows, width), dtype=object)
        for column in range(width):
            text[:, column] = [
                self._cell_string(value) for value in source[:, column]
            ]

        stats = self._column_stats(text)
        columns = list(df.columns)
        blocks = self._merge_blocks(width, columns, col_merge)

        equality_order = [
            i for i, _ in sorted(
                enumerate(stats),
                key=lambda x: (-x[1][0], -x[1][1], -x[1][2], x[0]),
            )
        ]
        prefix_order = [
            i for i, _ in sorted(
                enumerate(stats),
                key=lambda x: (-x[1][3], -x[1][0], -x[1][1], x[0]),
            )
        ]

        preferences = [equality_order, prefix_order]
        preferences.extend(self._block_candidates(text, stats, blocks))

        best_score = -1
        best_orders = None
        best_serialized = None

        for preference in preferences[:3]:
            repaired = self._constrained_order(
                width, preference, columns, one_way_dep, blocks
            )
            orders = [repaired[:] for _ in range(rows)]
            serialized = self._serialize(text, orders)
            score = self._trie_score(serialized)
            if score > best_score:
                best_score = score
                best_orders = orders
                best_serialized = serialized

        result, public_orders = self._materialize(
            df, source, best_orders, best_serialized
        )
        if result.shape != df.shape:
            raise RuntimeError("Reordering changed DataFrame shape")

        self._last_orders = public_orders
        return result, public_orders

